import{bQ as r,aZ as o,aL as i,u as n,G as e,I as d}from"./chunks/framework.C1gZXFVa.js";const m=JSON.parse('{"title":"撮合初始化链路","description":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。","frontmatter":{"title":"撮合初始化链路","description":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070503"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070503"}],["meta",{"property":"og:title","content":"撮合初始化链路 · TGEX"}],["meta",{"property":"og:description","content":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"撮合初始化链路 · TGEX"}],["meta",{"name":"twitter:description","content":"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"撮合初始化链路\\",\\"description\\":\\"撮合进程起来后，如何加载交易对、恢复未完结委托并逐步开放接单。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070503\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070503\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070503.md","filePath":"07.现货手册/05.核心交易流程/03.撮合初始化链路.md"}'),l={name:"pages/070503.md"};function s(h,t,p,g,b,c){const a=o("Flow");return i(),n("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="撮合初始化链路" tabindex="-1">撮合初始化链路 <a class="header-anchor" href="#撮合初始化链路" aria-label="Permalink to &quot;撮合初始化链路&quot;">​</a></h1><div class="doc-lead">撮合系统进程起来之后，撮合要先准备好交易对和计价规则，再按交易对把未完结委托挂回盘口，最后才对该交易对开放下单与撤单。</div><p>对应工程：<code>tgex-match</code>。下文只讲<strong>业务准备顺序</strong>，不展开类名与接口细节。</p><h2 id="先分清两层就绪" tabindex="-1">先分清两层就绪 <a class="header-anchor" href="#先分清两层就绪" aria-label="Permalink to &quot;先分清两层就绪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>进程已起来</td><td>服务可注册、全局撮合通道可用，<strong>不等于</strong>每个交易对都能下单</td></tr><tr><td>某交易对已开放</td><td>该交易对的未完结委托已恢复进订单簿，可以接受新的下单 / 撤单</td></tr></tbody></table><p>常见情况：元数据装完后，各交易对仍在<strong>并行恢复</strong>；有的对已经开放，有的对还在重试。</p><h2 id="总流程" tabindex="-1">总流程 <a class="header-anchor" href="#总流程" aria-label="Permalink to &quot;总流程&quot;">​</a></h2>',8)),d(a,{steps:["全局撮合通道就绪","Redis 未落库增量刷进数据库","拉取交易对与商户规则","装入用户限制与手续费","装入价格参考","按交易对并行恢复","开放接单或进入重试"]}),t[1]||(t[1]=e('<figure class="flow-board" aria-label="撮合初始化总图"><figcaption>INIT FLOW <span>进程起来之后</span></figcaption><ol class="flow-board-steps"><li>全局撮合通道就绪</li><li>Redis 队列 → MySQL（未落库增量）</li><li>交易对 / 商户交易对服务 → 本地规则</li><li>用户 / 账务 / 商户服务 → 禁交易、手续费、分成</li><li>行情服务 → 人民币价、最近成交价</li><li>按交易对并行：读 Redis 或 MySQL 未完结委托 → 挂回订单簿</li></ol><div class="flow-board-branch"><div><strong>恢复成功</strong><p>开放该交易对接单，可下单 / 撤单</p></div><div><strong>恢复失败</strong><p>进入失败集合，定时重试，该对暂时拒单</p></div></div></figure><h2 id="_1-全局通道先就绪" tabindex="-1">1. 全局通道先就绪 <a class="header-anchor" href="#_1-全局通道先就绪" aria-label="Permalink to &quot;1. 全局通道先就绪&quot;">​</a></h2><p>撮合进程启动后，会先准备好<strong>全局事件通道</strong>和订单簿基础设施（依赖 Redis）。<br> 此时整站可以处理内部事件；若后续「未落库数据刷库」多次失败，可能把全局通道关掉，表现为暂时整站拒写。</p><h2 id="_2-先刷未落库数据" tabindex="-1">2. 先刷未落库数据 <a class="header-anchor" href="#_2-先刷未落库数据" aria-label="Permalink to &quot;2. 先刷未落库数据&quot;">​</a></h2><p>启动时会<strong>同步</strong>处理：上次异常停机留在 <strong>Redis 队列</strong>里、尚未写入 <strong>MySQL</strong> 的增量（账户变动、委托、委托明细一类）。</p><p>目的：先把「上次没落完的账」尽量落完，再恢复各交易对盘口，避免内存状态和库不一致。</p><p>刷完后，会另起后台任务<strong>持续</strong>消费 Redis → 数据库，与后面的按交易对恢复并行。</p><h2 id="_3-加载交易对-关键" tabindex="-1">3. 加载交易对（关键） <a class="header-anchor" href="#_3-加载交易对-关键" aria-label="Permalink to &quot;3. 加载交易对（关键）&quot;">​</a></h2><p>从交易对 / 商户相关服务拉取：</p><table tabindex="0"><thead><tr><th>数据</th><th>来源（工程侧）</th><th>用途</th></tr></thead><tbody><tr><td>平台交易对</td><td>币种 / 交易对配置服务</td><td>知道有哪些 symbol、买卖币</td></tr><tr><td>商户启用交易对</td><td>商户交易对服务</td><td>哪些商户开了哪些对</td></tr></tbody></table><p><strong>没有可用交易对，后面无法按对恢复委托，也无法开放接单。</strong><br> 所以初始化链路里，交易对集合是否拉到，是第一道业务门槛。</p><h2 id="_4-装入规则与价格缓存" tabindex="-1">4. 装入规则与价格缓存 <a class="header-anchor" href="#_4-装入规则与价格缓存" aria-label="Permalink to &quot;4. 装入规则与价格缓存&quot;">​</a></h2><p>在启用商户列表基础上，继续从用户、账务、商户、行情等服务装入内存规则：</p><table tabindex="0"><thead><tr><th>内容</th><th>大致来源</th><th>用途</th></tr></thead><tbody><tr><td>禁止交易的用户</td><td>用户状态类服务</td><td>恢复后下单仍要拦截</td></tr><tr><td>平台币抵扣手续费</td><td>账务 / 手续费配置</td><td>成交计价</td></tr><tr><td>商户手续费分成</td><td>商户服务</td><td>分成计算</td></tr><tr><td>VIP 手续费</td><td>用户 / VIP 服务</td><td>成交计价</td></tr><tr><td>币种人民币价</td><td>商户币种 + 行情计价</td><td>展示与折算相关</td></tr><tr><td>各交易对最近成交价</td><td>行情服务</td><td>撮合侧价格参考</td></tr></tbody></table><p>这些在启动时先拉齐，避免「第一笔成交才去拼费率」。</p><h2 id="_5-按交易对恢复委托" tabindex="-1">5. 按交易对恢复委托 <a class="header-anchor" href="#_5-按交易对恢复委托" aria-label="Permalink to &quot;5. 按交易对恢复委托&quot;">​</a></h2><p>拿到交易对列表后，对每个交易对（并行）走恢复：</p>',17)),d(a,{steps:["创建该交易对引擎","暂时关闭该对接单","读取未完结委托","挂回订单簿","开放该对接单"]}),t[2]||(t[2]=e('<h3 id="从哪里读未完结委托" tabindex="-1">从哪里读未完结委托 <a class="header-anchor" href="#从哪里读未完结委托" aria-label="Permalink to &quot;从哪里读未完结委托&quot;">​</a></h3><p>由 Redis 中的「是否已热启动过」一类标记决定主路径：</p><table tabindex="0"><thead><tr><th>路径</th><th>数据来源</th><th>适用</th></tr></thead><tbody><tr><td>热恢复</td><td><strong>Redis</strong> 中该交易对未完结委托</td><td>常见重启，盘口还在缓存里</td></tr><tr><td>冷恢复</td><td><strong>MySQL</strong> 中未成交 / 部分成交委托</td><td>首次或标记要求走库</td></tr></tbody></table><p>个别交易对可能被配置为始终走数据库路径。<br> 另有一条非交易对通道（充值、提现、改账等内部事件），不挂普通买卖盘。</p><h3 id="热恢复时大致做什么" tabindex="-1">热恢复时大致做什么 <a class="header-anchor" href="#热恢复时大致做什么" aria-label="Permalink to &quot;热恢复时大致做什么&quot;">​</a></h3><ol><li>从 Redis 读出该交易对未完结委托。</li><li>需要时补齐相关用户的币币资产快照（Redis / 账务侧数据）到本地缓存。</li><li>把委托逐笔挂进该交易对订单簿。</li><li>推送或刷新深度。</li><li><strong>开放该交易对接单</strong>。</li></ol><h3 id="冷恢复时大致做什么" tabindex="-1">冷恢复时大致做什么 <a class="header-anchor" href="#冷恢复时大致做什么" aria-label="Permalink to &quot;冷恢复时大致做什么&quot;">​</a></h3><ol><li>按交易对从数据库查出未完结委托（会结合商户交易对信息）。</li><li>批量补齐涉及用户的钱包缓存。</li><li>同样挂簿，再开放接单。</li></ol><h3 id="失败与重试" tabindex="-1">失败与重试 <a class="header-anchor" href="#失败与重试" aria-label="Permalink to &quot;失败与重试&quot;">​</a></h3><p>某个交易对恢复失败时：</p><ul><li>通常<strong>不会</strong>拖垮整个进程；</li><li>该对进入失败集合，<strong>定时重试</strong>（先等一段时间，再周期性重试）；</li><li>重试成功前，该对对外下单 / 撤单应被拒绝。</li></ul><p>主流程只保证「各交易对恢复任务已提交」，<strong>不保证</strong>全部交易对同一时刻都已开放。</p><h2 id="_6-其它附属准备" tabindex="-1">6. 其它附属准备 <a class="header-anchor" href="#_6-其它附属准备" aria-label="Permalink to &quot;6. 其它附属准备&quot;">​</a></h2><p>若环境启用高频相关策略，还会从 Redis 恢复当日卖单计数一类辅助数据。<br> 运行期仍会定时刷新交易对、分成、汇率等——初始化不是装完就再也不变。</p><h2 id="_7-就绪怎么理解" tabindex="-1">7. 就绪怎么理解 <a class="header-anchor" href="#_7-就绪怎么理解" aria-label="Permalink to &quot;7. 就绪怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>大致条件</th><th>能做什么</th></tr></thead><tbody><tr><td>全局通道</td><td>进程正常且未因刷库失败关停</td><td>内部事件通道可用</td></tr><tr><td>规则就绪</td><td>交易对、费率、价格等已进内存</td><td>具备按规则处理的前提</td></tr><tr><td>单交易对开放</td><td>该对委托已挂簿且已开放接单</td><td>可接受该对下单 / 撤单</td></tr><tr><td>部分未完成</td><td>仍在失败重试</td><td>这些对暂时不可交易</td></tr></tbody></table><h2 id="_8-依赖哪些其它工程-中间件" tabindex="-1">8. 依赖哪些其它工程 / 中间件 <a class="header-anchor" href="#_8-依赖哪些其它工程-中间件" aria-label="Permalink to &quot;8. 依赖哪些其它工程 / 中间件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>用途</th></tr></thead><tbody><tr><td>Redis</td><td>未落库队列、热委托、资产快照、启动标记</td></tr><tr><td>MySQL</td><td>冷恢复委托、刷库落库目标</td></tr><tr><td>交易对 / 商户服务</td><td>交易对清单</td></tr><tr><td>用户服务</td><td>禁交易、VIP</td></tr><tr><td>账务相关服务</td><td>手续费抵扣、钱包快照</td></tr><tr><td>行情服务</td><td>最近价、人民币价</td></tr></tbody></table><p>建议：账务、交易对基础数据、行情至少部分可用后，再观察撮合侧「按交易对是否已开放」。</p><p>业务上的撮合语义见<a href="/pages/070501#match">业务流程 · 撮合与成交</a>。同组：<a href="/pages/070502">委托初始化链路</a>、<a href="/pages/070504">账务初始化链路</a>、<a href="/pages/070505">行情初始化链路</a>。</p>',20))])}const u=r(l,[["render",s]]);export{m as __pageData,u as default};
